<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ApiError } from '@/api/client';
import { downloadDocument, getDocuments, requestDocuments, type DocumentsPayload } from '@/api/documents';
import { getSession } from '@/api/session';
const route = useRoute(); const router = useRouter(); const data = ref<DocumentsPayload | null>(null); const error = ref<string | null>(null); const message = ref<string | null>(null); const working = ref(false); let timer: number | null = null;
const revisionId = () => String(route.params.revision);
const load = async () => { try { await getSession(); data.value = await getDocuments(revisionId()); const pending = data.value.artifacts.some((item) => ['pendiente', 'procesando'].includes(item.estado)); if (pending && timer === null) timer = window.setInterval(() => { void load(); }, 3000); if (!pending && timer !== null) { clearInterval(timer); timer = null; } } catch (reason) { if (reason instanceof ApiError && reason.status === 401) { await router.replace('/ingresar'); return; } error.value = reason instanceof ApiError ? reason.message : 'No se pudieron cargar los documentos.'; } };
const request = async () => { try { working.value = true; message.value = (await requestDocuments(revisionId())).message; await load(); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo solicitar la exportación.'; } finally { working.value = false; } };
const download = async (artifactId: string, format: 'docx' | 'pdf') => { try { working.value = true; const blob = await downloadDocument(artifactId, format); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `silabo-${data.value?.syllabus.code ?? 'asignatura'}-revision-${data.value?.revision.number}.${format}`; anchor.click(); URL.revokeObjectURL(url); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : 'No se pudo descargar el archivo.'; } finally { working.value = false; } };
onMounted(() => { void load(); }); onBeforeUnmount(() => { if (timer !== null) clearInterval(timer); });
</script>
<template><main class="app-page"><header class="app-header"><div><p class="eyebrow">Documentos aprobados</p><h1>{{ data?.syllabus.subject ?? 'Documentos' }}</h1><p v-if="data">{{ data.syllabus.code }} · {{ data.syllabus.period }} · Revisión {{ data.revision.number }}</p></div><button class="back-link" @click="router.back()">Volver</button></header><p v-if="message" class="save-status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><template v-if="data"><section class="detail-card"><h2>Aprobación</h2><p>Aprobada por {{ data.revision.approved_by }} el {{ new Date(data.revision.approved_at).toLocaleString('es-EC') }}.</p><button :disabled="working" @click="request">Generar DOCX y PDF</button></section><section class="detail-card"><h2>Solicitudes de exportación</h2><div v-if="data.artifacts.length" class="table-wrap"><table><thead><tr><th>Solicitud</th><th>Estado</th><th>Progreso</th><th>Archivos</th></tr></thead><tbody><tr v-for="artifact in data.artifacts" :key="artifact.id"><td>{{ new Date(artifact.requested_at).toLocaleString('es-EC') }}<small>{{ artifact.renderer_label }}</small></td><td>{{ artifact.estado }}<small v-if="artifact.execution?.mensaje_error">{{ artifact.execution.mensaje_error }}</small></td><td>{{ artifact.execution?.progreso ?? (artifact.estado === 'completado' ? 100 : 0) }}%</td><td class="process-actions"><template v-if="artifact.estado === 'completado'"><button :disabled="working" @click="download(artifact.id, 'docx')">Descargar DOCX</button><button :disabled="working" @click="download(artifact.id, 'pdf')">Descargar PDF</button></template><span v-else>En proceso</span></td></tr></tbody></table></div><p v-else class="empty-state">Todavía no se solicitaron documentos para esta revisión.</p></section></template><p v-else-if="!error">Cargando documentos…</p></main></template>
